/* ═══ ARENA ═══ */
window.crearCombateArena=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let jA=document.getElementById('adm-arena-jugador-a').value,jB=document.getElementById('adm-arena-jugador-b').value,desc=document.getElementById('adm-arena-descripcion').value.trim(),lim=parseInt(document.getElementById('adm-arena-limite').value)||5;if(!jA||!jB){mostrarNotificacion("Selecciona los dos jugadores.","error","⚔️");return;}if(jA===jB){mostrarNotificacion("Los dos jugadores deben ser diferentes.","error","⚔️");return;}if(!desc){mostrarNotificacion("Añade una descripción.","error","⚔️");return;}let id="arena_"+Date.now();if(!baseDatos.arena)baseDatos.arena={};baseDatos.arena[id]={id,jugadorA:jA,jugadorB:jB,descripcion:desc,limitePf:lim,estado:"abierto",ganador:null,apuestas:{},boteA:0,boteB:0,fechaCreacion:new Date().toLocaleDateString()};logAdmin('Crear combate Arena',`${jA.toUpperCase()} vs ${jB.toUpperCase()}: "${desc}"`);reproducirSonido('exito');mostrarNotificacion(`Combate "${desc}" abierto en la Arena.`,'exito','🎰');};
window.cerrarApuestasCombate=function(cid){if(!userSesion||userSesion.toLowerCase()!=="srwiwa")return;if(baseDatos.arena[cid]){baseDatos.arena[cid].estado="cerrado";guardarBD();reproducirSonido('cerrar');}};
window.resolverCombateArena=function(cid,gl){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let c=baseDatos.arena[cid];if(!c)return;c.ganador=gl;c.estado="resuelto";if(!c.apuestas)c.apuestas={};let bG=gl==='A'?(c.boteA||0):(c.boteB||0),bP=gl==='A'?(c.boteB||0):(c.boteA||0);let gan=[],per=[];Object.keys(c.apuestas).forEach(uid=>{let ap=c.apuestas[uid];if(ap.lado===gl)gan.push({uid,cantidad:ap.cantidad});else per.push({uid,cantidad:ap.cantidad});});if(gan.length>0&&bG>0){gan.forEach(g=>{let prop=g.cantidad/bG,ganancia=Math.floor(bP*prop),tot=g.cantidad+ganancia;if(baseDatos.jugadores[g.uid]){baseDatos.jugadores[g.uid].pf=(baseDatos.jugadores[g.uid].pf||0)+tot;inyectarEntradaDiarioAutomaticaPara(g.uid,`🎰 ARENA: ¡Acertaste en [${c.descripcion}]! +${tot} PF.`);}});per.forEach(g=>{if(baseDatos.jugadores[g.uid])inyectarEntradaDiarioAutomaticaPara(g.uid,`🎰 ARENA: Apuesta perdida en [${c.descripcion}]. −${g.cantidad} PF.`);});}else if(gan.length===0&&per.length>0){per.forEach(g=>{if(baseDatos.jugadores[g.uid]){baseDatos.jugadores[g.uid].pf=(baseDatos.jugadores[g.uid].pf||0)+g.cantidad;inyectarEntradaDiarioAutomaticaPara(g.uid,`🎰 ARENA: Nadie apostó al ganador. Tus ${g.cantidad} PF devueltos.`);}});}let nG=gl==='A'?c.jugadorA:c.jugadorB;logAdmin('⚔️','Resolver combate Arena',`${c.descripcion} → 🏆 ${nG.toUpperCase()}`);guardarBD();reproducirSonido('exito');mostrarNotificacion(`Combate resuelto. Ganador: ${nG.toUpperCase()}`,'exito','🏆');};
window.apostarEnCombate=async function(cid,lado){if(!userSesion)return;if(jugadorBaneado(userSesion)){mostrarNotificacion(`🚫 Estás baneado de Eventos. Motivo: ${baseDatos.jugadores[userSesion].baneado.motivo}`,'error','🚫');return;}let c=baseDatos.arena[cid];if(!c||c.estado!=="abierto"){mostrarNotificacion("Las apuestas están cerradas.","error","🔒");return;}if(c.jugadorA===userSesion||c.jugadorB===userSesion){mostrarNotificacion("No puedes apostar en tu propio combate.","error","⚔️");return;}if(c.apuestas&&c.apuestas[userSesion]){mostrarNotificacion("Ya has apostado en este combate.","error","🎰");return;}let ie=document.getElementById(`arena-input-${cid}`),cantidad=parseInt(ie?ie.value:0)||0;if(cantidad<=0){mostrarNotificacion("Introduce una cantidad válida.","error","🎰");return;}if(cantidad>c.limitePf){mostrarNotificacion(`El máximo permitido es ${c.limitePf} PF.`,"error","🎰");return;}let u=baseDatos.jugadores[userSesion];if((u.pf||0)<cantidad){mostrarNotificacion(`PF insuficientes. Tienes ${u.pf||0} PF.`,"error","🔮");return;}let nJ=lado==='A'?c.jugadorA:c.jugadorB;let cf=await mostrarConfirmacion({icono:'🎰',titulo:'Confirmar apuesta',descripcion:`Apostar ${cantidad} PF a que ${nJ.toUpperCase()} gana\n"${c.descripcion}"`,textoConfirmar:'Apostar',sonidoConfirmar:'apuesta'});if(!cf)return;u.pf=(u.pf||0)-cantidad;if(!c.apuestas)c.apuestas={};c.apuestas[userSesion]={lado,cantidad};if(lado==='A')c.boteA=(c.boteA||0)+cantidad;else c.boteB=(c.boteB||0)+cantidad;inyectarEntradaDiarioAutomatica(`🎰 APUESTA: Aposté ${cantidad} PF a ${nJ.toUpperCase()} en [${c.descripcion}].`);guardarBD();mostrarNotificacion(`${cantidad} PF a ${nJ.toUpperCase()}.`,'exito','🎰','Apuesta registrada',true);};
window.cambiarArenaSubtab=function(tipo){reproducirSonido('tab');document.querySelectorAll('.arena-subtab').forEach(t=>t.classList.remove('active'));document.querySelectorAll('.arena-subview').forEach(v=>v.classList.remove('active'));let te=document.getElementById(`asub-${tipo}`),ve=document.getElementById(`arena-form-${tipo}`);if(te)te.classList.add('active');if(ve)ve.classList.add('active');};
function crearFilaOpcionEncuesta(valor){let row=document.createElement('div');row.className='encuesta-opcion-row';row.innerHTML=`<input type="text" class="admin-input encuesta-opcion-input" placeholder="Opción" value="${valor?escaparHTML(valor):''}"><button type="button" class="btn-del-opcion" onclick="this.parentElement.remove()">✕</button>`;return row;}
function resetearOpcionesEncuesta(){let box=document.getElementById('adm-encuesta-opciones-list');if(!box)return;box.innerHTML='';box.appendChild(crearFilaOpcionEncuesta('Sí'));box.appendChild(crearFilaOpcionEncuesta('No'));}
window.anadirOpcionEncuesta=function(){let box=document.getElementById('adm-encuesta-opciones-list');if(!box)return;if(box.children.length>=8){mostrarNotificacion("Máximo 8 opciones por encuesta.","error","🗳️");return;}box.appendChild(crearFilaOpcionEncuesta(''));};
window.crearEncuestaArena=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let pregunta=document.getElementById('adm-encuesta-pregunta').value.trim(),lim=parseInt(document.getElementById('adm-encuesta-limite').value)||5;if(!pregunta){mostrarNotificacion("Escribe la pregunta de la encuesta.","error","🗳️");return;}let opciones=[];document.querySelectorAll('#adm-encuesta-opciones-list .encuesta-opcion-input').forEach(i=>{let v=i.value.trim();if(v)opciones.push(v);});if(opciones.length<2){mostrarNotificacion("Añade al menos 2 opciones.","error","🗳️");return;}let id="arena_"+Date.now();if(!baseDatos.arena)baseDatos.arena={};baseDatos.arena[id]={id,tipo:'encuesta',descripcion:pregunta,opciones,limitePf:lim,estado:"abierto",ganador:null,apuestas:{},botes:{},fechaCreacion:new Date().toLocaleDateString()};logAdmin('Crear encuesta Arena',`"${pregunta}" (${opciones.length} opciones)`);document.getElementById('adm-encuesta-pregunta').value='';resetearOpcionesEncuesta();reproducirSonido('exito');mostrarNotificacion(`Encuesta "${pregunta}" publicada en la Arena.`,'exito','🗳️');};
window.apostarEnEncuesta=async function(cid,opIdx){if(!userSesion)return;if(jugadorBaneado(userSesion)){mostrarNotificacion(`🚫 Estás baneado de Eventos. Motivo: ${baseDatos.jugadores[userSesion].baneado.motivo}`,'error','🚫');return;}let c=baseDatos.arena[cid];if(!c||c.estado!=="abierto"){mostrarNotificacion("Las votaciones están cerradas.","error","🔒");return;}if(c.apuestas&&c.apuestas[userSesion]){mostrarNotificacion("Ya has apostado en esta encuesta.","error","🗳️");return;}opIdx=Number(opIdx);let ie=document.getElementById(`encuesta-input-${cid}`),cantidad=parseInt(ie?ie.value:0)||0;if(cantidad<=0){mostrarNotificacion("Introduce una cantidad válida.","error","🗳️");return;}if(cantidad>c.limitePf){mostrarNotificacion(`El máximo permitido es ${c.limitePf} PF.`,"error","🗳️");return;}let u=baseDatos.jugadores[userSesion];if((u.pf||0)<cantidad){mostrarNotificacion(`PF insuficientes. Tienes ${u.pf||0} PF.`,"error","🔮");return;}let opcionTxt=c.opciones[opIdx];let cf=await mostrarConfirmacion({icono:'🗳️',titulo:'Confirmar apuesta',descripcion:`Apostar ${cantidad} PF a "${opcionTxt}"\n"${c.descripcion}"`,textoConfirmar:'Apostar',sonidoConfirmar:'apuesta'});if(!cf)return;u.pf=(u.pf||0)-cantidad;if(!c.apuestas)c.apuestas={};c.apuestas[userSesion]={opcion:opIdx,cantidad};if(!c.botes)c.botes={};c.botes[opIdx]=(c.botes[opIdx]||0)+cantidad;inyectarEntradaDiarioAutomatica(`🗳️ ENCUESTA: Aposté ${cantidad} PF a "${opcionTxt}" en [${c.descripcion}].`);guardarBD();mostrarNotificacion(`${cantidad} PF a "${opcionTxt}".`,'exito','🗳️','Apuesta registrada',true);};
window.resolverEncuestaArena=function(cid,opIdx){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let c=baseDatos.arena[cid];if(!c||c.tipo!=='encuesta')return;opIdx=Number(opIdx);c.ganador=opIdx;c.estado="resuelto";if(!c.apuestas)c.apuestas={};if(!c.botes)c.botes={};let total=0;c.opciones.forEach((_,i)=>{total+=(c.botes[i]||0);});let bG=c.botes[opIdx]||0,bP=total-bG,gan=[],per=[];Object.keys(c.apuestas).forEach(uid=>{let ap=c.apuestas[uid];if(Number(ap.opcion)===opIdx)gan.push({uid,cantidad:ap.cantidad});else per.push({uid,cantidad:ap.cantidad});});if(gan.length>0&&bG>0){gan.forEach(g=>{let prop=g.cantidad/bG,ganancia=Math.floor(bP*prop),tot=g.cantidad+ganancia;if(baseDatos.jugadores[g.uid]){baseDatos.jugadores[g.uid].pf=(baseDatos.jugadores[g.uid].pf||0)+tot;inyectarEntradaDiarioAutomaticaPara(g.uid,`🗳️ ENCUESTA: ¡Acertaste en [${c.descripcion}]! +${ganancia} PF.`);}});per.forEach(g=>{if(baseDatos.jugadores[g.uid])inyectarEntradaDiarioAutomaticaPara(g.uid,`🗳️ ENCUESTA: Apuesta perdida en [${c.descripcion}]. −${g.cantidad} PF.`);});}else if(gan.length===0&&per.length>0){per.forEach(g=>{if(baseDatos.jugadores[g.uid]){baseDatos.jugadores[g.uid].pf=(baseDatos.jugadores[g.uid].pf||0)+g.cantidad;inyectarEntradaDiarioAutomaticaPara(g.uid,`🗳️ ENCUESTA: Nadie acertó la opción ganadora. Tus ${g.cantidad} PF devueltos.`);}});}guardarBD();reproducirSonido('exito');mostrarNotificacion(`Encuesta resuelta. Opción ganadora: ${c.opciones[opIdx].toUpperCase()}`,'exito','🏆');};
function renderTarjetaEncuestaPublica(c){let total=0;c.opciones.forEach((_,i)=>{total+=(c.botes&&c.botes[i])||0;});let ma=c.apuestas&&c.apuestas[userSesion]?c.apuestas[userSesion]:null;let bH=c.estado==='abierto'?'<span class="arena-badge badge-abierto">🟢 ABIERTA</span>':c.estado==='cerrado'?'<span class="arena-badge badge-cerrado">🔒 CERRADA</span>':'<span class="arena-badge badge-resuelto">✅ RESUELTA</span>';let inputRow=(c.estado==='abierto'&&!ma)?`<div class="arena-apostar-row" style="margin-top:0;padding-top:0;border-top:none"><span style="font-size:10px;color:var(--txt-muted);font-family:var(--font-display)">APUESTA OPCIONAL (máx. ${c.limitePf} PF):</span><input type="number" id="encuesta-input-${c.id}" class="arena-input-apuesta" min="1" max="${c.limitePf}" value="1"></div>`:'';let opcionesHtml=c.opciones.map((op,i)=>{let boteI=(c.botes&&c.botes[i])||0,pct=total>0?Math.round((boteI/total)*100):0,cardClass='encuesta-opcion-card';if(c.estado==='resuelto'){cardClass+=(Number(c.ganador)===i?' ganadora':' perdedora');}let votarBtn=(c.estado==='abierto'&&!ma)?`<button class="btn-votar-opcion" onclick="apostarEnEncuesta('${c.id}','${i}')">Votar "${escaparHTML(op)}"</button>`:'';let miVotoTag=(ma&&Number(ma.opcion)===i)?`<div style="font-size:9px;color:var(--neon-arena);font-family:var(--font-display);margin-top:4px">✅ Tu apuesta: ${ma.cantidad} PF</div>`:'';return `<div class="${cardClass}"><div class="encuesta-opcion-top"><div class="encuesta-opcion-nombre">${escaparHTML(op)}${c.estado==='resuelto'&&Number(c.ganador)===i?' 🏆':''}</div><div class="encuesta-opcion-datos">${boteI} PF · ${pct}%</div></div><div class="encuesta-opcion-barra"><div class="encuesta-opcion-barra-fill" style="width:${pct}%"></div></div>${votarBtn}${miVotoTag}</div>`;}).join('');let rH='';if(c.estado==='resuelto'&&ma){if(Number(ma.opcion)===Number(c.ganador)){let bG=(c.botes&&c.botes[c.ganador])||0,bP2=total-bG,prop=bG>0?ma.cantidad/bG:0,gan=Math.floor(bP2*prop),tot=ma.cantidad+gan;rH=`<div class="arena-resultado resultado-gane">🏆 ¡ACERTASTE! +${gan} ganancia = <strong>${tot} PF</strong></div>`;}else rH=`<div class="arena-resultado resultado-perdi">💸 Fallaste. Perdiste ${ma.cantidad} PF.</div>`;}else if(c.estado==='resuelto'&&!ma){rH=`<div class="arena-resultado resultado-no-parti">— No participaste en esta encuesta.</div>`;}return `<div class="arena-combate-card ${c.estado==='resuelto'?'resuelto':''}"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex-wrap:wrap;gap:6px"><div style="font-family:var(--font-display);font-size:12px;color:var(--txt-primary);font-weight:700">🗳️ ${escaparHTML(c.descripcion)} ${bH}</div><div style="font-size:10px;color:var(--txt-muted)">Bote total: <span style="color:var(--neon-arena);font-weight:700;font-family:var(--font-display)">${total} PF</span></div></div>${inputRow}<div class="encuesta-opciones-render">${opcionesHtml}</div>${rH}</div>`;}
function renderizarArenaPublica(){let box=document.getElementById('arena-lista-combates'),sb=document.getElementById('arena-stats-personales');if(!box)return;box.innerHTML='';if(!baseDatos.arena||!Object.keys(baseDatos.arena).length){box.innerHTML=`<div style="text-align:center;padding:60px 20px;color:var(--txt-muted);border:1px dashed var(--gris-700);border-radius:var(--r-xl);background:var(--bg-elevated)"><div style="font-size:36px;margin-bottom:12px">🎰</div><div style="font-family:var(--font-display);font-size:12px;text-transform:uppercase;letter-spacing:2px">Arena Vacía</div><div style="font-size:11px;margin-top:6px">El Mercader aún no ha abierto ningún combate.</div></div>`;return;}if(sb&&userSesion){let g=0,p=0;Object.values(baseDatos.arena).forEach(c=>{if(c.estado==='resuelto'&&c.apuestas&&c.apuestas[userSesion]){let ma=c.apuestas[userSesion];if((c.tipo||'duelo')==='encuesta'){if(Number(ma.opcion)===Number(c.ganador))g++;else p++;}else{if(ma.lado===c.ganador)g++;else p++;}}});sb.innerHTML=`<div class="arena-stat-chip">Ganadas: <span>${g}</span></div><div class="arena-stat-chip">Perdidas: <span>${p}</span></div>`;}let combates=Object.values(baseDatos.arena).sort((a,b)=>({abierto:0,cerrado:1,resuelto:2}[a.estado]||0)-({abierto:0,cerrado:1,resuelto:2}[b.estado]||0));combates.forEach(c=>{if((c.tipo||'duelo')==='encuesta'){box.innerHTML+=renderTarjetaEncuestaPublica(c);return;}let bt=(c.boteA||0)+(c.boteB||0),pA=bt>0?Math.round(((c.boteA||0)/bt)*100):50,pB=100-pA;let ma=c.apuestas&&c.apuestas[userSesion]?c.apuestas[userSesion]:null,sp=c.jugadorA===userSesion||c.jugadorB===userSesion;let bH=c.estado==='abierto'?'<span class="arena-badge badge-abierto">🟢 ABIERTAS</span>':c.estado==='cerrado'?'<span class="arena-badge badge-cerrado">🔒 CERRADAS</span>':'<span class="arena-badge badge-resuelto">✅ RESUELTO</span>';let lA='lado-a',lB='lado-b';if(c.estado==='resuelto'){lA+=(c.ganador==='A'?' ganador':' perdedor');lB+=(c.ganador==='B'?' ganador':' perdedor');}let aH='';if(c.estado==='abierto'&&!sp){if(ma)aH=`<div class="arena-mi-apuesta">✅ Apostaste ${ma.cantidad} PF a ${escaparHTML((ma.lado==='A'?c.jugadorA:c.jugadorB).toUpperCase())}</div>`;else aH=`<div class="arena-apostar-row"><span style="font-size:10px;color:var(--txt-muted);font-family:var(--font-display)">APUESTA (máx. ${c.limitePf} PF):</span><input type="number" id="arena-input-${c.id}" class="arena-input-apuesta" min="1" max="${c.limitePf}" value="1"><button class="btn-aposta-a" onclick="apostarEnCombate('${c.id}','A')">A ${escaparHTML(c.jugadorA.toUpperCase())}</button><button class="btn-aposta-b" onclick="apostarEnCombate('${c.id}','B')">B ${escaparHTML(c.jugadorB.toUpperCase())}</button></div>`;}else if(sp&&c.estado==='abierto'){aH=`<div class="arena-mi-apuesta" style="color:var(--txt-muted)">⚔️ Eres participante de este combate</div>`;}let rH='';if(c.estado==='resuelto'&&ma){if(ma.lado===c.ganador){let bG=c.ganador==='A'?(c.boteA||0):(c.boteB||0),bP2=c.ganador==='A'?(c.boteB||0):(c.boteA||0),prop=bG>0?ma.cantidad/bG:0,gan=Math.floor(bP2*prop),tot=ma.cantidad+gan;rH=`<div class="arena-resultado resultado-gane">🏆 ¡ACERTASTE! +${gan} ganancia = <strong>${tot} PF</strong></div>`;}else rH=`<div class="arena-resultado resultado-perdi">💸 Fallaste. Perdiste ${ma.cantidad} PF.</div>`;}else if(c.estado==='resuelto'&&!ma&&!sp){rH=`<div class="arena-resultado resultado-no-parti">— No participaste en este combate.</div>`;}box.innerHTML+=`<div class="arena-combate-card ${c.estado==='resuelto'?'resuelto':''}"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex-wrap:wrap;gap:6px"><div style="font-family:var(--font-display);font-size:12px;color:var(--txt-primary);font-weight:700">${escaparHTML(c.descripcion)} ${bH}</div><div style="font-size:10px;color:var(--txt-muted)">Bote: <span style="color:var(--neon-arena);font-weight:700;font-family:var(--font-display)">${bt} PF</span></div></div><div class="arena-vs-row"><div class="arena-lado ${lA}"><div class="arena-jugador azul">${escaparHTML(c.jugadorA.toUpperCase())}</div><div class="arena-bote-num">${c.boteA||0} PF</div><div class="arena-bote-pct">${pA}% del bote</div>${c.estado==='resuelto'&&c.ganador==='A'?'<div style="font-size:18px;margin-top:5px">🏆</div>':''}</div><div class="arena-vs-badge">VS</div><div class="arena-lado ${lB}"><div class="arena-jugador rojo">${escaparHTML(c.jugadorB.toUpperCase())}</div><div class="arena-bote-num">${c.boteB||0} PF</div><div class="arena-bote-pct">${pB}% del bote</div>${c.estado==='resuelto'&&c.ganador==='B'?'<div style="font-size:18px;margin-top:5px">🏆</div>':''}</div></div><div class="arena-barra"><div class="arena-barra-a" style="width:${pA}%"></div><div class="arena-barra-b" style="width:${pB}%"></div></div>${aH}${rH}</div>`;});}

/* ═══ CÁMARA DE COMERCIO ═══ */
window.crearTruequeCamara=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let jA=document.getElementById('adm-camara-jugador-a').value,oA=document.getElementById('adm-camara-objeto-a').value.trim(),jB=document.getElementById('adm-camara-jugador-b').value,oB=document.getElementById('adm-camara-objeto-b').value.trim(),cat=document.getElementById('adm-camara-categoria').value;if(!jA||!jB){mostrarNotificacion("Selecciona los dos jugadores.","error","🏛️");return;}if(jA===jB){mostrarNotificacion("Los dos jugadores deben ser diferentes.","error","🏛️");return;}if(!oA||!oB){mostrarNotificacion("Indica los objetos de ambos jugadores.","error","📦");return;}if(!cat){mostrarNotificacion("Selecciona la categoría del intercambio.","error","🏛️");return;}let cd=CAMARA_CATEGORIAS[cat];if(!cd){mostrarNotificacion("Categoría inválida.","error","🏛️");return;}let uA=baseDatos.jugadores[jA],uB=baseDatos.jugadores[jB];if(!uA||!uB){mostrarNotificacion("Uno o ambos jugadores no encontrados.","error","🏛️");return;}if((uA.pf||0)<cd.coste){mostrarNotificacion(`${jA.toUpperCase()} no tiene suficientes PF (necesita ${cd.coste}, tiene ${uA.pf||0}).`,"error","🔮");return;}if((uB.pf||0)<cd.coste){mostrarNotificacion(`${jB.toUpperCase()} no tiene suficientes PF (necesita ${cd.coste}, tiene ${uB.pf||0}).`,"error","🔮");return;}uA.pf=(uA.pf||0)-cd.coste;uB.pf=(uB.pf||0)-cd.coste;let tid="camara_"+Date.now();if(!baseDatos.camara)baseDatos.camara={};baseDatos.camara[tid]={id:tid,jugadorA:jA,objetoA:oA,jugadorB:jB,objetoB:oB,categoria:cat,costePorJugador:cd.coste,estado:"votacion",votos:{},fechaCreacion:new Date().toLocaleDateString()};inyectarEntradaDiarioAutomaticaPara(jA,`🏛️ CÁMARA: El Mercader propuso un trueque contigo. Entregas '${oA}' a ${jB.toUpperCase()} a cambio de '${oB}'. Coste: ${cd.coste} PF retenidos.`);inyectarEntradaDiarioAutomaticaPara(jB,`🏛️ CÁMARA: El Mercader propuso un trueque contigo. Entregas '${oB}' a ${jA.toUpperCase()} a cambio de '${oA}'. Coste: ${cd.coste} PF retenidos.`);logAdmin('Crear trueque Cámara',`${jA.toUpperCase()} (${oA}) ⇄ ${jB.toUpperCase()} (${oB}) [${cat}]`);document.getElementById('adm-camara-objeto-a').value='';document.getElementById('adm-camara-objeto-b').value='';reproducirSonido('trueque');mostrarNotificacion(`${jA.toUpperCase()} y ${jB.toUpperCase()} han retenido ${cd.coste} PF cada uno.`,'exito','🏛️','Trueque publicado');};
window.votarTruequeCamara=function(tid,tipo){if(!userSesion)return;if(jugadorBaneado(userSesion)){mostrarNotificacion(`🚫 Estás baneado de Eventos. Motivo: ${baseDatos.jugadores[userSesion].baneado.motivo}`,'error','🚫');return;}let t=baseDatos.camara[tid];if(!t||t.estado!=="votacion"){mostrarNotificacion("Este trueque ya no está en votación.","error","🏛️");return;}if(t.jugadorA===userSesion||t.jugadorB===userSesion){mostrarNotificacion("No puedes votar en tu propio trueque.","error","🏛️");return;}if(t.votos&&t.votos[userSesion]){mostrarNotificacion("Ya emitiste tu voto.","error","🏛️");return;}if(!t.votos)t.votos={};t.votos[userSesion]=tipo;guardarBD();reproducirSonido('voto');mostrarNotificacion(tipo==='SI'?'Has aprobado el trueque.':'Has rechazado el trueque.','info',tipo==='SI'?'👍':'👎');};
window.resolverTruequeCamara=function(tid,res){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let t=baseDatos.camara[tid];if(!t){mostrarNotificacion("Trueque no encontrado.","error","🏛️");return;}let uA=baseDatos.jugadores[t.jugadorA],uB=baseDatos.jugadores[t.jugadorB],c=t.costePorJugador||0;if(res==='ACEPTADO'){t.estado="completado";inyectarEntradaDiarioAutomaticaPara(t.jugadorA,`🏛️ CÁMARA ACEPTADA: Trueque '${t.objetoA}' → '${t.objetoB}' completado con ${t.jugadorB.toUpperCase()}. Coste definitivo: ${c} PF.`);inyectarEntradaDiarioAutomaticaPara(t.jugadorB,`🏛️ CÁMARA ACEPTADA: Trueque '${t.objetoB}' → '${t.objetoA}' completado con ${t.jugadorA.toUpperCase()}. Coste definitivo: ${c} PF.`);guardarBD();reproducirSonido('exito');mostrarNotificacion('Los PF no se devuelven.','exito','✅','Trueque aceptado');}else{if(uA)uA.pf=(uA.pf||0)+c;if(uB)uB.pf=(uB.pf||0)+c;t.estado="rechazado";inyectarEntradaDiarioAutomaticaPara(t.jugadorA,`🏛️ CÁMARA RECHAZADA: El trueque con ${t.jugadorB.toUpperCase()} fue cancelado. Te han devuelto ${c} PF.`);inyectarEntradaDiarioAutomaticaPara(t.jugadorB,`🏛️ CÁMARA RECHAZADA: El trueque con ${t.jugadorA.toUpperCase()} fue cancelado. Te han devuelto ${c} PF.`);guardarBD();reproducirSonido('cerrar');mostrarNotificacion(`Se han devuelto ${c} PF a cada jugador.`,'info','❌','Trueque rechazado');}};
function renderizarCamaraPublica(){let box=document.getElementById('contenedor-intercambios-camara');if(!box)return;box.innerHTML='';if(!baseDatos.camara||!Object.keys(baseDatos.camara).length){box.innerHTML=`<div style="text-align:center;padding:60px 20px;color:var(--txt-muted);border:1px dashed var(--gris-700);border-radius:var(--r-xl);background:var(--bg-elevated)"><div style="font-size:36px;margin-bottom:12px">🏛️</div><div style="font-family:var(--font-display);font-size:12px;text-transform:uppercase;letter-spacing:2px">Cámara Vacía</div><div style="font-size:11px;margin-top:6px">El Mercader aún no ha publicado ningún trueque.</div></div>`;return;}let todos=Object.values(baseDatos.camara);let activos=todos.filter(t=>t.estado==='votacion');let resueltos=todos.filter(t=>t.estado!=='votacion').sort((a,b)=>({completado:0,rechazado:1}[a.estado]||0)-({completado:0,rechazado:1}[b.estado]||0));function pintarTrueque(t){let cd=CAMARA_CATEGORIAS[t.categoria]||{label:'Desconocida',icon:'❓',badgeClass:'',coste:0},si=t.jugadorA===userSesion||t.jugadorB===userSesion,yv=t.votos&&t.votos[userSesion],vs=t.votos?Object.values(t.votos).filter(v=>v==='SI').length:0,vn=t.votos?Object.values(t.votos).filter(v=>v==='NO').length:0;let bE=t.estado==='votacion'?'<span class="arena-badge badge-abierto">🗳️ VOTACIÓN</span>':t.estado==='completado'?'<span class="arena-badge badge-resuelto">✅ COMPLETADO</span>':'<span class="arena-badge badge-cerrado">❌ RECHAZADO</span>';let rH='';if(t.estado==='completado'&&si)rH=`<div class="arena-resultado resultado-gane" style="margin-top:10px">✅ Trueque aceptado. Coste final: ${t.costePorJugador} PF.</div>`;else if(t.estado==='rechazado'&&si)rH=`<div class="arena-resultado resultado-perdi" style="margin-top:10px">❌ Trueque rechazado. Se te han devuelto ${t.costePorJugador} PF.</div>`;let vH='';if(t.estado==='votacion'&&!si){if(yv)vH=`<div class="arena-mi-apuesta" style="margin-top:10px">✅ Votaste: <strong>${yv==='SI'?'👍 A favor':'👎 En contra'}</strong></div>`;else vH=`<div style="display:flex;gap:8px;margin-top:12px;padding-top:12px;border-top:1px solid var(--borde);flex-wrap:wrap"><span style="font-size:10px;color:var(--txt-muted);font-family:var(--font-display);align-self:center">¿Apruebas este trueque?</span><button style="padding:7px 14px;background:rgba(30,158,115,.08);border:1px solid rgba(30,158,115,.25);color:var(--neon-legal);border-radius:var(--r-sm);font-family:var(--font-display);font-size:10px;font-weight:700;cursor:pointer;text-transform:uppercase" onclick="votarTruequeCamara('${t.id}','SI')">👍 Aprobar</button><button style="padding:7px 14px;background:rgba(216,41,63,.08);border:1px solid rgba(216,41,63,.25);color:#e2646f;border-radius:var(--r-sm);font-family:var(--font-display);font-size:10px;font-weight:700;cursor:pointer;text-transform:uppercase" onclick="votarTruequeCamara('${t.id}','NO')">👎 Rechazar</button></div>`;}else if(t.estado==='votacion'&&si){vH=`<div class="arena-mi-apuesta" style="color:var(--txt-muted);margin-top:8px">⚖️ Eres parte de este trueque</div>`;}return `<div class="intercambio-card" style="border-left-color:${t.estado==='votacion'?'var(--neon-intercambio)':t.estado==='completado'?'var(--neon-legal)':'#e2646f'}"><div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px;flex-wrap:wrap;gap:6px"><div><div style="font-family:var(--font-display);font-size:11px;color:var(--neon-intercambio);font-weight:700;margin-bottom:4px">${escaparHTML(t.jugadorA.toUpperCase())} ⇄ ${escaparHTML(t.jugadorB.toUpperCase())} ${bE}</div><span class="cat-badge ${cd.badgeClass}">${cd.icon} ${escaparHTML(cd.label)}</span></div><div style="display:flex;gap:4px;align-items:center"><span class="votos-badge votos-si">👍 ${vs}</span><span class="votos-badge votos-no">👎 ${vn}</span></div></div><div style="display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center;background:rgba(0,0,0,.2);padding:12px;border-radius:var(--r-md)"><div style="text-align:center"><div style="font-size:9px;color:#6f9cc4;font-family:var(--font-display);font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:5px">${escaparHTML(t.jugadorA.toUpperCase())} entrega</div><div style="font-size:14px;font-weight:700;color:var(--txt-primary)">📦 ${escaparHTML(t.objetoA)}</div></div><div style="font-family:var(--font-display);font-size:18px;font-weight:900;color:var(--neon-intercambio);text-align:center">⇄</div><div style="text-align:center"><div style="font-size:9px;color:#e2646f;font-family:var(--font-display);font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:5px">${escaparHTML(t.jugadorB.toUpperCase())} entrega</div><div style="font-size:14px;font-weight:700;color:var(--txt-primary)">📦 ${escaparHTML(t.objetoB)}</div></div></div>${vH}${rH}</div>`;}
  let html=activos.map(pintarTrueque).join('');
  if(!activos.length)html=`<div style="text-align:center;padding:30px 20px;color:var(--txt-muted);font-family:var(--font-display);font-size:11px">Sin trueques en votación ahora mismo.</div>`;
  if(resueltos.length){html+=`<div style="margin:22px 0 12px;padding-top:16px;border-top:1px solid var(--borde);font-family:var(--font-display);font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:var(--txt-muted)">📜 Trueques Resueltos</div>`+resueltos.map(pintarTrueque).join('');}
  box.innerHTML=html;
}
function renderizarAdminCamara(){let box=document.getElementById('adm-camara-trueques-activos');if(!box)return;box.innerHTML='';if(!baseDatos.camara||!Object.keys(baseDatos.camara).length){box.innerHTML='<div style="color:var(--txt-muted);font-size:10px;text-align:center;padding:10px;font-family:var(--font-display)">No hay trueques activos.</div>';return;}Object.values(baseDatos.camara).forEach(t=>{if(t.estado!=='votacion')return;let cd=CAMARA_CATEGORIAS[t.categoria]||{label:'?',icon:'❓',coste:0},vs=t.votos?Object.values(t.votos).filter(v=>v==='SI').length:0,vn=t.votos?Object.values(t.votos).filter(v=>v==='NO').length:0;box.innerHTML+=`<div class="admin-camara-card"><div style="font-size:11px;color:var(--neon-intercambio);font-weight:700;margin-bottom:4px;font-family:var(--font-display)">${escaparHTML(t.jugadorA.toUpperCase())} ⇄ ${escaparHTML(t.jugadorB.toUpperCase())}</div><div style="font-size:10px;color:var(--txt-secondary);margin-bottom:5px">${cd.icon} ${cd.label} · ${t.costePorJugador} PF c/u</div><div style="font-size:10px;color:var(--txt-muted);margin-bottom:7px">📦 ${escaparHTML(t.objetoA)} ⇄ 📦 ${escaparHTML(t.objetoB)}</div><div style="font-size:10px;color:var(--txt-muted);margin-bottom:7px">Votos: 👍 ${vs} · 👎 ${vn}</div><div class="admin-btns-row"><button class="btn-admin-sm legal" onclick="resolverTruequeCamara('${t.id}','ACEPTADO')">✅ Aceptar</button><button class="btn-admin-sm danger" onclick="resolverTruequeCamara('${t.id}','RECHAZADO')">❌ Rechazar</button></div></div>`;});}

/* ═══ ADMIN ═══ */
window.restablecerComprasDiariasDesdeMercader=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let t=document.getElementById('adm-reset-usuario').value;if(!t){mostrarNotificacion("Selecciona un entrenador.","error","🔄");return;}baseDatos.jugadores[t].comprasDisponibles=MAX_COMPRAS;baseDatos.jugadores[t].comprasHoy={};baseDatos.jugadores[t].ultimaRecarga=Date.now();logAdmin('Resetear compras diarias',`${t.toUpperCase()}`);reproducirSonido('exito');mostrarNotificacion("Compras reiniciadas.","exito","🔄");};
window.ajustarComprasLegales=function(op){
  if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}
  let uid=document.getElementById('adm-reset-usuario').value,cant=parseInt(document.getElementById('adm-compras-cantidad').value)||0;
  if(!uid||cant<=0){mostrarNotificacion("Revisa los campos.","error","🛒");return;}
  let u=baseDatos.jugadores[uid],hoy=new Date().toDateString();
  if(!u.comprasHoy||u.comprasHoy._fecha!==hoy)u.comprasHoy={_fecha:hoy};
  let delta=(op==='SUMAR'?cant:-cant),nuevo=Math.max(0,Math.min(MAX_COMPRAS,(u.comprasHoy._global||0)+delta));
  u.comprasHoy._global=nuevo;
  u.comprasDisponibles=Math.max(0,MAX_COMPRAS-nuevo);
  logAdmin('Ajustar compras legales',`${uid.toUpperCase()}: ${op==='SUMAR'?'+':'-'}${cant} → ahora ${nuevo}/${MAX_COMPRAS}`);
  document.getElementById('adm-compras-cantidad').value='';
  reproducirSonido('exito');
  mostrarNotificacion(`${uid.toUpperCase()}: ahora ${nuevo}/${MAX_COMPRAS} compras legales.`,"exito","🛒");
  guardarBD();
  if(userSesion===uid){actualizarComprasPorTiempo();refrescarPantallaGamer();renderInitializeLoaders();}
};
window.ajustarComprasIlegal=function(op){
  if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}
  let uid=document.getElementById('adm-reset-usuario').value;
  if(!uid){mostrarNotificacion("Selecciona un entrenador.","error","🟣");return;}
  let u=baseDatos.jugadores[uid],hoy=new Date().toDateString();
  if(!u.comprasHoy||u.comprasHoy._fecha!==hoy)u.comprasHoy={_fecha:hoy};
  let nuevo=Math.max(0,Math.min(1,(u.comprasHoy._illegal||0)+(op==='SUMAR'?1:-1)));
  u.comprasHoy._illegal=nuevo;
  logAdmin('Ajustar ilegalidad',`${uid.toUpperCase()}: ahora ${nuevo}/1 ilegal`);
  reproducirSonido('exito');
  mostrarNotificacion(`${uid.toUpperCase()}: ahora ${nuevo}/1 ilegalidad usada.`,"exito","🟣");
  guardarBD();
  if(userSesion===uid){actualizarComprasPorTiempo();refrescarPantallaGamer();renderInitializeLoaders();}
};
/* Helper: comprueba si un jugador está baneado de Tienda/Gacha/Eventos */
function jugadorBaneado(uid){return !!(baseDatos.jugadores[uid]&&baseDatos.jugadores[uid].baneado&&baseDatos.jugadores[uid].baneado.activo);}
window.banearJugador=function(){
  if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}
  let t=document.getElementById('adm-ban-usuario').value;
  let motivo=(document.getElementById('adm-ban-motivo').value||'').trim();
  if(!t||!baseDatos.jugadores[t]){mostrarNotificacion("Entrenador no encontrado.","error","🚫");return;}
  if(!motivo){mostrarNotificacion("Debes escribir el motivo del baneo.","error","🚫");return;}
  baseDatos.jugadores[t].baneado={activo:true,motivo:motivo,fecha:new Date().toLocaleDateString()};
  inyectarEntradaDiarioAutomaticaPara(t,`🚫 HAS SIDO BANEADO de la Tienda, el Gacha y los Eventos. Motivo: ${motivo}`);
  logAdmin('Banear jugador',`${t.toUpperCase()}: ${motivo}`);
  document.getElementById('adm-ban-motivo').value='';
  reproducirSonido('error');
  guardarBD();
  mostrarNotificacion(`${t.toUpperCase()} ha sido baneado de Tienda, Gacha y Eventos.`,'exito','🚫');
  actualizarSelectorUsuariosBanco();
  if(userSesion===t)refrescarPantallaGamer();
};
window.desbanearJugador=function(){
  if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}
  let t=document.getElementById('adm-ban-usuario').value;
  if(!t||!baseDatos.jugadores[t]){mostrarNotificacion("Entrenador no encontrado.","error","🚫");return;}
  if(!jugadorBaneado(t)){mostrarNotificacion("Ese entrenador no está baneado.","error","🚫");return;}
  baseDatos.jugadores[t].baneado.activo=false;
  inyectarEntradaDiarioAutomaticaPara(t,`✅ Tu baneo de Tienda, Gacha y Eventos ha sido levantado. Ya puedes volver a usarlos.`);
  logAdmin('Desbanear jugador',`${t.toUpperCase()}`);
  reproducirSonido('exito');
  guardarBD();
  mostrarNotificacion(`${t.toUpperCase()} ha sido desbaneado.`,'exito','✅');
  actualizarSelectorUsuariosBanco();
  if(userSesion===t)refrescarPantallaGamer();
};
window.restablecerGachaDiarioDesdeMercader=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let t=document.getElementById('adm-reset-gacha-usuario').value;if(!t||!baseDatos.jugadores[t]){mostrarNotificacion("Entrenador no encontrado.","error","⚡");return;}baseDatos.jugadores[t].ultimoHackeo=0;logAdmin('Resetear gacha diario',`${t.toUpperCase()}`);reproducirSonido('exito');mostrarNotificacion(`Gacha de ${t.toUpperCase()} reiniciado.`,"exito","⚡");};
window.emitirOrdenEconomicaGlobal=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}baseDatos.eventoSistema=document.getElementById('adm-evento-economico').value;logAdmin('Orden económica global',`${baseDatos.eventoSistema}`);reproducirSonido('exito');mostrarNotificacion("Orden de Red distribuida.","exito","📢");};
window.cargarTituloManualEnAdmin=function(){let uid=document.getElementById('adm-titulo-usuario').value,inp=document.getElementById('adm-titulo-texto');if(!uid||!inp)return;let u=baseDatos.jugadores[uid];inp.value=(u&&u.tituloManual)?u.tituloManual:'';};
window.asignarTituloManual=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let uid=document.getElementById('adm-titulo-usuario').value,txt=document.getElementById('adm-titulo-texto').value.trim();if(!uid){mostrarNotificacion("Selecciona un entrenador.","error","🏷️");return;}if(!txt){mostrarNotificacion("Escribe el texto del título.","error","🏷️");return;}let u=baseDatos.jugadores[uid];u.tituloManual=txt;u.tituloActivo='manual';inyectarEntradaDiarioAutomaticaPara(uid,`[ADMIN] El Mercader te otorgó el título 🏷️ "${txt}".`);logAdmin('Asignar título',`${uid.toUpperCase()}: "${txt}"`);reproducirSonido('exito');mostrarNotificacion(`Título "${txt}" otorgado a ${uid.toUpperCase()}.`,"exito","🏷️");if(userSesion===uid)renderizarTitulosYTemas();};
window.quitarTituloManual=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let uid=document.getElementById('adm-titulo-usuario').value;if(!uid){mostrarNotificacion("Selecciona un entrenador.","error","🏷️");return;}let u=baseDatos.jugadores[uid];if(!u.tituloManual){mostrarNotificacion("Este entrenador no tiene título manual.","error","🏷️");return;}delete u.tituloManual;if(u.tituloActivo==='manual')u.tituloActivo=null;logAdmin('Quitar título',`${uid.toUpperCase()}`);document.getElementById('adm-titulo-texto').value='';reproducirSonido('click');mostrarNotificacion(`Título manual eliminado de ${uid.toUpperCase()}.`,"info","🗑️");if(userSesion===uid)renderizarTitulosYTemas();};
window.ajustarVidasEntrenador=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let uid=document.getElementById('adm-vidas-usuario').value,ini=parseInt(document.getElementById('adm-vidas-iniciales').value)||20,act=parseInt(document.getElementById('adm-vidas-actuales').value);if(!uid){mostrarNotificacion("Selecciona un entrenador.","error","❤️");return;}if(isNaN(act)){mostrarNotificacion("Introduce las vidas actuales.","error","❤️");return;}act=Math.max(0,Math.min(act,ini));baseDatos.jugadores[uid].vidasTotales=ini;baseDatos.jugadores[uid].vidasActuales=act;if(act<=0)baseDatos.jugadores[uid].lockeStatus='perdido';inyectarEntradaDiarioAutomaticaPara(uid,`[ADMIN] El Mercader ajustó tus vidas → ❤️ ${act}/${ini}`);logAdmin('Ajustar vidas',`${uid.toUpperCase()} → ${act}/${ini}`);reproducirSonido('exito');mostrarNotificacion(`${uid.toUpperCase()}: vidas ajustadas a ${act}/${ini}`,'exito','❤️');};
window.cargarVidasEnAdmin=function(){let uid=document.getElementById('adm-vidas-usuario').value;if(!uid||!baseDatos.jugadores[uid])return;let u=baseDatos.jugadores[uid];document.getElementById('adm-vidas-iniciales').value=u.vidasTotales||20;document.getElementById('adm-vidas-actuales').value=(u.vidasActuales!==undefined)?u.vidasActuales:(u.vidasTotales||20);};
window.modificarFondosEntrenador=function(op){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let uid=document.getElementById('adm-banco-usuario').value,cant=parseInt(document.getElementById('adm-banco-cantidad').value)||0;if(!uid||cant<=0){mostrarNotificacion("Revisa los campos.","error","💰");return;}baseDatos.jugadores[uid].dinero+=(op==='SUMAR'?cant:-cant);logAdmin('Modificar dinero',`${uid.toUpperCase()}: ${op==='SUMAR'?'+':'-'}${cant} P₠`);document.getElementById('adm-banco-cantidad').value='';reproducirSonido('exito');mostrarNotificacion(`${op==='SUMAR'?'+':'-'}${cant} P₠ para ${uid.toUpperCase()}.`,"exito","💰");};
window.modificarPFEntrenador=function(op){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let uid=document.getElementById('adm-banco-usuario').value,cant=parseInt(document.getElementById('adm-pf-cantidad').value)||0;if(!uid||cant<=0){mostrarNotificacion("Revisa los campos.","error","🔮");return;}baseDatos.jugadores[uid].pf=(baseDatos.jugadores[uid].pf||0)+(op==='SUMAR'?cant:-cant);logAdmin('Modificar PF',`${uid.toUpperCase()}: ${op==='SUMAR'?'+':'-'}${cant} PF`);document.getElementById('adm-pf-cantidad').value='';reproducirSonido('exito');mostrarNotificacion(`${op==='SUMAR'?'+':'-'}${cant} PF para ${uid.toUpperCase()}.`,"exito","🔮");};
window.conmutarEstadoTienda=function(prop,estado){if(!userSesion||userSesion.toLowerCase()!=="srwiwa")return;baseDatos[prop]=estado;guardarBD();reproducirSonido(estado?'exito':'cerrar');if(prop==='illegalOpen'&&estado){registrarActividadGlobal('Sistema','☢️ La Red de Ilegalidades ha sido desbloqueada por el Mercader.',(()=>{let d=new Date();return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}:${String(d.getSeconds()).padStart(2,'0')}`;})());}};
window.ajustarCamposFormularioMercader=function(){let t=document.getElementById('ins-tienda').value;document.getElementById('form-bloque-legal-cat').style.display=t==='legal'?'block':'none';document.getElementById('form-bloque-pack-detalles').style.display=t==='pack'?'block':'none';document.getElementById('form-bloque-illegal-detalles').style.display=t==='illegal'?'block':'none';document.getElementById('bloque-ins-pf').style.display=t!=='illegal'?'block':'none';document.getElementById('lbl-ins-precio').textContent=t==='illegal'?'Coste (PF):':'Coste (P₠):';};
window.inyectarObjetoNuevoMaster=function(){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let t=document.getElementById('ins-tienda').value,n=document.getElementById('ins-nombre').value.trim(),p=parseInt(document.getElementById('ins-precio').value)||0,s=parseInt(document.getElementById('ins-stock').value)||0;if(!n){mostrarNotificacion("Falta el nombre del producto.","error","📦");return;}let nuevo={id:Date.now(),tienda:t,stock:s,icon:document.getElementById('ins-icono').value.trim()||'📦',nombre:n};if(t==='legal'){nuevo.cat=document.getElementById('ins-cat-legal').value;nuevo.precio=p;nuevo.pf=parseInt(document.getElementById('ins-pf').value)||0;}else if(t==='pack'){nuevo.cat='Pack Especial';nuevo.precio=p;nuevo.pf=parseInt(document.getElementById('ins-pf').value)||0;nuevo.desc=document.getElementById('ins-pack-desc').value.trim();nuevo.estrategia=document.getElementById('ins-pack-estrategia').value.trim();}else if(t==='illegal'){nuevo.cat='Hack de Sistema';nuevo.precioPf=p;nuevo.desc=document.getElementById('ins-illegal-desc').value.trim();nuevo.beneficio=document.getElementById('ins-illegal-beneficio').value.trim();nuevo.castigo=document.getElementById('ins-illegal-castigo').value.trim();}if(!baseDatos.productos)baseDatos.productos=[];baseDatos.productos.push(nuevo);logAdmin('Publicar producto',`${nuevo.icon} ${n} (${t})`);document.getElementById('ins-nombre').value='';document.getElementById('ins-precio').value='';document.getElementById('ins-illegal-beneficio').value='';document.getElementById('ins-illegal-castigo').value='';document.getElementById('ins-illegal-desc').value='';reproducirSonido('exito');mostrarNotificacion(`${nuevo.icon} ${n} publicado.`,"exito","📦");};
window.actualizarPropertyProducto=function(id,prop,val){if(!userSesion||userSesion.toLowerCase()!=="srwiwa")return;let i=baseDatos.productos.findIndex(p=>p.id===id);if(i!==-1){baseDatos.productos[i][prop]=parseInt(val)||0;guardarBD();}};
window.actualizarPropertyProductoTexto=function(id,prop,val){if(!userSesion||userSesion.toLowerCase()!=="srwiwa")return;let i=baseDatos.productos.findIndex(p=>p.id===id);if(i!==-1){baseDatos.productos[i][prop]=val;guardarBD();}};
window.eliminarTodosLosProductosDeTienda=async function(tienda){if(!userSesion||userSesion.toLowerCase()!=="srwiwa")return;let cf=await mostrarConfirmacion({icono:'🗑️',titulo:`¿Vaciar ${tienda==='legal'?'Tienda Legal':tienda==='pack'?'Shop PF Pack':'Ilegalidades'}?`,descripcion:'Se eliminarán todos los productos publicados en esta tienda. Esta acción no se puede deshacer.',textoConfirmar:'Vaciar tienda',tipo:'sacrificio'});if(!cf)return;baseDatos.productos=baseDatos.productos.filter(p=>p.tienda!==tienda);logAdmin('Vaciar tienda',`${tienda}`);redibujarConsolaAdminMaster();mostrarNotificacion('Tienda vaciada.','exito','🗑️');};
window.eliminarProductoMaster=async function(id){if(!userSesion||userSesion.toLowerCase()!=="srwiwa"){mostrarNotificacion("Acceso denegado.","error","🔒");return;}let cf=await mostrarConfirmacion({icono:'🗑️',titulo:'Eliminar producto',descripcion:'Esta acción no se puede deshacer.',textoConfirmar:'Eliminar',tipo:'peligro'});if(cf){let pd=baseDatos.productos&&baseDatos.productos.find(p=>p.id===id);logAdmin('🛒','Eliminar producto',pd?(pd.icon+' '+pd.nombre):'ID '+id);baseDatos.productos=baseDatos.productos.filter(p=>p.id!==id);guardarBD();mostrarNotificacion("Producto eliminado.","info","🗑️",null,true);}};
function actualizarSelectorUsuariosBanco(){let sb=document.getElementById('adm-banco-usuario'),sr=document.getElementById('adm-reset-usuario'),sg=document.getElementById('adm-reset-gacha-usuario'),sbn=document.getElementById('adm-ban-usuario'),sa=document.getElementById('adm-arena-jugador-a'),sb2=document.getElementById('adm-arena-jugador-b'),sv=document.getElementById('adm-vidas-usuario'),scA=document.getElementById('adm-camara-jugador-a'),scB=document.getElementById('adm-camara-jugador-b'),sp=document.getElementById('adm-pf-usuario'),st=document.getElementById('adm-titulo-usuario'),spa=document.getElementById('pvp-jugador-a'),spb=document.getElementById('pvp-jugador-b');if(!sb||!sr)return;let _srVal=sr?sr.value:'',_sbnVal=sbn?sbn.value:'';[sb,sr,sg,sbn,sa,sb2,sv,scA,scB,sp,st,spa,spb].forEach(el=>{if(el)el.innerHTML='';});Object.keys(baseDatos.jugadores).forEach(id=>{let u=baseDatos.jugadores[id],vi=`❤️ ${u.vidasActuales??u.vidasTotales??20}/${u.vidasTotales??20}`;if(sb)sb.innerHTML+=`<option value="${id}">${id.toUpperCase()} (${u.dinero} P₠)</option>`;if(sr){let cH=u.comprasHoy&&u.comprasHoy._fecha===new Date().toDateString()?u.comprasHoy:{};sr.innerHTML+=`<option value="${id}">${id.toUpperCase()} (${cH._global||0}/${MAX_COMPRAS} legal · ${cH._illegal||0}/1 ilegal)</option>`;}if(sg)sg.innerHTML+=`<option value="${id}">${id.toUpperCase()}</option>`;if(sbn)sbn.innerHTML+=`<option value="${id}">${id.toUpperCase()}${jugadorBaneado(id)?' 🚫 (BANEADO)':''}</option>`;if(sa)sa.innerHTML+=`<option value="${id}">${id.toUpperCase()}</option>`;if(sb2)sb2.innerHTML+=`<option value="${id}">${id.toUpperCase()}</option>`;if(sv)sv.innerHTML+=`<option value="${id}">${id.toUpperCase()} (${vi})</option>`;if(scA)scA.innerHTML+=`<option value="${id}">${id.toUpperCase()} (${u.pf||0} PF)</option>`;if(scB)scB.innerHTML+=`<option value="${id}">${id.toUpperCase()} (${u.pf||0} PF)</option>`;if(sp)sp.innerHTML+=`<option value="${id}">${id.toUpperCase()} (${u.pf||0} PF)</option>`;if(st)st.innerHTML+=`<option value="${id}">${id.toUpperCase()}${u.tituloManual?' (🏷️ '+u.tituloManual+')':''}</option>`;if(spa)spa.innerHTML+=`<option value="${id}">${id.toUpperCase()}</option>`;if(spb)spb.innerHTML+=`<option value="${id}">${id.toUpperCase()}</option>`;});if(sr&&_srVal)sr.value=_srVal;if(sbn&&_sbnVal)sbn.value=_sbnVal;if(sv)sv.onchange=window.cargarVidasEnAdmin;if(sv&&sv.value)window.cargarVidasEnAdmin();if(st&&st.value)window.cargarTituloManualEnAdmin();var c=(baseDatos&&baseDatos.campeones)||{};['adm-campeon-finalísima'].forEach(function(sid){var el=document.getElementById(sid);if(!el)return;var val=c.finalísima||'';el.innerHTML='<option value="">— Sin campeón —</option>'+Object.keys(baseDatos.jugadores).map(function(id){return '<option value="'+id+'"'+(id===val?' selected':'')+'>'+id.toUpperCase()+'</option>';}).join('');});
  // Poblar lista dinámica de campeones por torneos
  var torneosLista=document.getElementById('adm-campeon-torneos-lista');
  if(torneosLista){
    var torneosActual=Array.isArray(c.torneos)?c.torneos:(c.torneos?[c.torneos]:[]);
    if(!torneosActual.length) torneosActual=[''];
    torneosLista.innerHTML='';
    torneosActual.forEach(function(val){ agregarGanadorTorneosConValor(val); });
  }
  // Poblar lista dinámica de campeones por vidas
  var vidasLista=document.getElementById('adm-campeon-vidas-lista');
  if(vidasLista){
    var vidasActual=Array.isArray(c.vidas)?c.vidas:(c.vidas?[c.vidas]:[]);
    if(!vidasActual.length) vidasActual=[''];
    vidasLista.innerHTML='';
    vidasActual.forEach(function(val){ agregarGanadorVidasConValor(val); });
  }refrescarSelectsPersonalizados();}
function renderizarAdminArena(){let box=document.getElementById('adm-arena-combates-activos');if(!box)return;box.innerHTML='';if(!baseDatos.arena||!Object.keys(baseDatos.arena).length){box.innerHTML='<div style="color:var(--txt-muted);font-size:10px;text-align:center;padding:10px;font-family:var(--font-display)">No hay combates activos.</div>';return;}Object.values(baseDatos.arena).forEach(c=>{if(c.estado==='resuelto')return;if((c.tipo||'duelo')==='encuesta'){let total=0;c.opciones.forEach((_,i)=>{total+=(c.botes&&c.botes[i])||0;});let detalle=c.opciones.map((op,i)=>`${escaparHTML(op)}: ${(c.botes&&c.botes[i])||0} PF`).join(' · ');let botonesOpcion=c.opciones.map((op,i)=>`<button class="btn-admin-sm legal" onclick="resolverEncuestaArena('${c.id}','${i}')">🏆 ${escaparHTML(op.toUpperCase())}</button>`).join('');box.innerHTML+=`<div class="admin-arena-card"><div style="font-size:11px;color:var(--neon-arena);font-weight:700;margin-bottom:5px;font-family:var(--font-display)">🗳️ ${escaparHTML(c.descripcion)}</div><div style="font-size:10px;color:var(--txt-secondary);margin-bottom:5px">${c.estado.toUpperCase()} — Bote total: ${total} PF</div><div style="font-size:10px;color:var(--txt-muted);margin-bottom:7px">${detalle}</div><div class="admin-btns-row">${c.estado==='abierto'?`<button class="btn-admin-sm packs" onclick="cerrarApuestasCombate('${c.id}')">🔒 Cerrar</button>`:''}${botonesOpcion}</div></div>`;return;}box.innerHTML+=`<div class="admin-arena-card"><div style="font-size:11px;color:var(--neon-arena);font-weight:700;margin-bottom:5px;font-family:var(--font-display)">${escaparHTML(c.descripcion)}</div><div style="font-size:10px;color:var(--txt-secondary);margin-bottom:7px"><span style="color:#6f9cc4">${escaparHTML(c.jugadorA.toUpperCase())}</span> vs <span style="color:#e2646f">${escaparHTML(c.jugadorB.toUpperCase())}</span> — ${c.estado.toUpperCase()} — Bote: ${(c.boteA||0)+(c.boteB||0)} PF</div><div class="admin-btns-row">${c.estado==='abierto'?`<button class="btn-admin-sm packs" onclick="cerrarApuestasCombate('${c.id}')">🔒 Cerrar</button>`:''}<button class="btn-admin-sm legal" onclick="resolverCombateArena('${c.id}','A')">🏆 Gana ${escaparHTML(c.jugadorA.toUpperCase())}</button><button class="btn-admin-sm danger" onclick="resolverCombateArena('${c.id}','B')">🏆 Gana ${escaparHTML(c.jugadorB.toUpperCase())}</button></div></div>`;});}
function redibujarConsolaAdminMaster(){document.getElementById('chk-open-legal').checked=baseDatos.legalOpen!==false;document.getElementById('chk-open-pack').checked=baseDatos.packOpen!==false;document.getElementById('chk-open-illegal').checked=baseDatos.illegalOpen!==false;let chkRadio=document.getElementById('chk-radio-activada');if(chkRadio)chkRadio.checked=!!(baseDatos.radio&&baseDatos.radio.activada);if(baseDatos.eventoSistema)document.getElementById('adm-evento-economico').value=baseDatos.eventoSistema;actualizarSelectorUsuariosBanco();renderizarAdminArena();renderizarAdminCamara();renderizarInventarioGlobalAdmin();renderizarListaRadioAdmin();}

window.renderizarInventarioGlobalAdmin=function(){
  let al=document.getElementById('admin-inventario-global');
  if(!al)return;
  let busq=(document.getElementById('editor-buscar')?.value||'').toLowerCase().trim();
  let filtroTienda=document.getElementById('editor-filtro-tienda')?.value||'';
  let lista=(baseDatos.productos||[]).filter(p=>{
    if(filtroTienda && p.tienda!==filtroTienda) return false;
    if(busq && !p.nombre.toLowerCase().includes(busq)) return false;
    return true;
  });
  if(!lista.length){al.innerHTML='<div style="color:var(--txt-muted);font-size:11px;text-align:center;padding:24px;font-family:var(--font-display)">Sin productos que coincidan.</div>';return;}
  al.innerHTML='';
  lista.forEach(p=>{
    let esI=p.tienda==='illegal', esPack=p.tienda==='pack';
    let tiendaColor=esI?'var(--neon-ilegal)':(esPack?'var(--neon-packs)':'var(--neon-legal)');
    let tiendaLabel=esI?'ILEGAL':(esPack?'PACK':'LEGAL');
    let card=document.createElement('div');
    card.className='admin-item-card';
    card.style.cssText='position:relative;border-left:3px solid '+tiendaColor;
    let html=`<button class="btn-del-item" onclick="eliminarProductoMaster(${p.id})">✕</button>`;
    html+=`<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px">
      <span style="font-family:var(--font-display);font-size:8px;font-weight:700;color:${tiendaColor};background:${tiendaColor}18;padding:2px 6px;border-radius:99px;letter-spacing:.5px">${tiendaLabel}</span>
      <span style="color:var(--txt-muted);font-size:9px;font-family:var(--font-display)">${p.qty&&p.qty>1?'x'+p.qty+' ':''}${p.cat||''}</span>
    </div>`;
    // Icono + nombre editable
    html+=`<div style="display:flex;gap:6px;margin-bottom:8px">
      <input type="text" value="${escaparHTML(p.icon||'📦')}" class="admin-input" style="margin-bottom:0;width:46px;text-align:center;font-size:16px;padding:6px 4px" oninput="actualizarPropertyProductoTexto(${p.id},'icon',this.value)">
      <input type="text" value="${escaparHTML(p.nombre)}" class="admin-input" style="margin-bottom:0;flex:1;font-weight:700;color:var(--txt-primary)" oninput="actualizarPropertyProductoTexto(${p.id},'nombre',this.value)">
    </div>`;
    // Precio + Stock
    html+=`<div class="admin-item-row" style="margin-bottom:8px">
      <div class="admin-field"><label>${esI?'PF':'Coste P₠'}</label><input type="number" value="${esI?(p.precioPf||0):(p.precio||0)}" class="admin-input" style="margin-bottom:0;width:90px" oninput="actualizarPropertyProducto(${p.id},'${esI?'precioPf':'precio'}',this.value)"></div>
      <div class="admin-field"><label>Stock</label><input type="number" value="${p.stock}" class="admin-input" style="margin-bottom:0;width:70px" oninput="actualizarPropertyProducto(${p.id},'stock',this.value)"></div>
      ${!esI?`<div class="admin-field"><label>Bono PF</label><input type="number" value="${p.pf||0}" class="admin-input" style="margin-bottom:0;width:70px" oninput="actualizarPropertyProducto(${p.id},'pf',this.value)"></div>`:''}
    </div>`;
    // Contenido del pack / descripción
    if(esPack){
      html+=`<div style="margin-bottom:6px"><label style="font-size:9px;color:var(--txt-muted);font-family:var(--font-display);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:2px">Contenido del pack</label><input type="text" value="${escaparHTML(p.desc||'')}" class="admin-input" style="margin-bottom:0;font-size:11px" oninput="actualizarPropertyProductoTexto(${p.id},'desc',this.value)"></div>`;
      html+=`<div><label style="font-size:9px;color:var(--txt-muted);font-family:var(--font-display);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:2px">Estrategia</label><input type="text" value="${escaparHTML(p.estrategia||'')}" class="admin-input" style="margin-bottom:0;font-size:11px" oninput="actualizarPropertyProductoTexto(${p.id},'estrategia',this.value)"></div>`;
    } else if(esI){
      html+=`<div style="margin-bottom:6px"><label style="font-size:9px;color:var(--txt-muted);font-family:var(--font-display);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:2px">Descripción</label><input type="text" value="${escaparHTML(p.desc||'')}" class="admin-input" style="margin-bottom:0;font-size:11px" oninput="actualizarPropertyProductoTexto(${p.id},'desc',this.value)"></div>`;
      html+=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
        <div><label style="font-size:9px;color:var(--neon-ilegal);font-family:var(--font-display);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:2px">✅ Beneficio</label><input type="text" value="${escaparHTML(p.beneficio||'')}" class="admin-input" style="margin-bottom:0;font-size:11px" oninput="actualizarPropertyProductoTexto(${p.id},'beneficio',this.value)"></div>
        <div><label style="font-size:9px;color:#e2646f;font-family:var(--font-display);text-transform:uppercase;letter-spacing:.4px;display:block;margin-bottom:2px">⚠️ Castigo</label><input type="text" value="${escaparHTML(p.castigo||'')}" class="admin-input" style="margin-bottom:0;font-size:11px" oninput="actualizarPropertyProductoTexto(${p.id},'castigo',this.value)"></div>
      </div>`;
    }
    card.innerHTML=html;
    al.appendChild(card);
  });
}

